import * as THREE from "three";

import type { ColorRGBA, Vector3 } from "./ros";
import type { Pose } from "./transforms";

export type BaseShape = {
  pose: Pose;
  scale: Vector3;
  color?: ColorRGBA;
};

export type MouseEventObject = {
  object: BaseShape;
  instanceIndex?: number;
};

export type CameraState = {
  distance: number;
  perspective: boolean;
  phi: number;
  target: readonly [number, number, number];
  targetOffset: readonly [number, number, number];
  targetOrientation: readonly [number, number, number, number];
  thetaOffset: number;
  fovy: number;
  near: number;
  far: number;
};

export const DEFAULT_CAMERA_STATE: CameraState = {
  distance: 20,
  perspective: true,
  phi: 60,
  target: [0, 0, 0],
  targetOffset: [0, 0, 0],
  targetOrientation: [0, 0, 0, 1],
  thetaOffset: 45,
  fovy: 45,
  near: 0.5,
  far: 5000,
};

export type OrbitControlsConfig = {
  screenSpacePanning: boolean;
  mouseButtons: {
    LEFT: number;
    RIGHT: number;
  };
  touches: {
    ONE: number;
    TWO: number;
  };
  keys: {
    LEFT: string;
    RIGHT: string;
    UP: string;
    BOTTOM: string;
  };
};

export const DEFAULT_ORBIT_CONTROLS_CONFIG: OrbitControlsConfig = {
  screenSpacePanning: false,
  mouseButtons: {
    LEFT: THREE.MOUSE.PAN,
    RIGHT: THREE.MOUSE.ROTATE,
  },
  touches: {
    ONE: THREE.TOUCH.PAN,
    TWO: THREE.TOUCH.DOLLY_ROTATE,
  },
  keys: { LEFT: "KeyA", RIGHT: "KeyD", UP: "KeyW", BOTTOM: "KeyS" },
};
